import type { HTMLAttributes } from 'react'

import { cx } from '~/lib/cx'
import styles from './kbd.module.scss'

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  size?: 'sm' | 'md'
}

/** A single key cap. Wrap several in a `role="group"` for shortcuts. */
export function Kbd({ size = 'md', className, ...props }: KbdProps) {
  return (
    <kbd
      className={cx(styles.root, size === 'sm' && styles.sm, className)}
      {...props}
    />
  )
}

@use 'styles' as vz;

.root {
  display: inline-flex;
  height: 1.375rem;
  min-width: 1.375rem;
  align-items: center;
  justify-content: center;
  padding-inline: vz.space(1.5);
  border: 1px solid vz.color('border');
  border-bottom-width: 2px;
  border-radius: vz.radius('xs');
  background: vz.color('muted');
  color: vz.color('muted-foreground');
  font-family: inherit;
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  user-select: none;
}

.sm {
  height: 1.125rem;
  min-width: 1.125rem;
  padding-inline: vz.space(1);
  font-size: 0.625rem;
}
